use std::{fs::{self,File},path::{Path,PathBuf},sync::atomic::AtomicBool};
use crate::{archive,download::LockedArchive,manifest::cache_provenance,CatalogEntry,PayloadError,PayloadManifest,PayloadProgress,Sha256Digest};
pub struct PrepareRequest<'a>{pub entry:&'a CatalogEntry,pub cache_root:&'a Path,pub progress:&'a dyn Fn(PayloadProgress),pub cancel:&'a AtomicBool}
pub struct ReadyGpuPayload{payload_id:String,generation:Sha256Digest,payload_manifest_sha256:Sha256Digest,files_directory:PathBuf,manifest:PayloadManifest,provenance_path:PathBuf}
impl ReadyGpuPayload{pub fn payload_id(&self)->&str{&self.payload_id}pub fn generation(&self)->&Sha256Digest{&self.generation}pub fn files_directory(&self)->&Path{&self.files_directory}pub fn manifest(&self)->&PayloadManifest{&self.manifest}pub fn provenance_path(&self)->&Path{&self.provenance_path}pub(crate)fn payload_manifest_sha256(&self)->&Sha256Digest{&self.payload_manifest_sha256}}
pub fn prepare(request:PrepareRequest<'_>)->Result<ReadyGpuPayload,PayloadError>{let root=request.cache_root.join("gpu-payload").join("v1");let mut locked=LockedArchive::acquire(&root,request.entry)?;locked.download(request.progress,request.cancel)?;locked.verify(request.progress,request.cancel)?;prepare_verified_archive(request.entry,locked.path(),&root,request.progress,request.cancel)}
pub(crate) fn prepare_verified_archive(entry:&CatalogEntry,archive:&Path,root:&Path,progress:&dyn Fn(PayloadProgress),cancel:&AtomicBool)->Result<ReadyGpuPayload,PayloadError>{let generation=entry.archive_sha256();let final_dir=root.join(generation.as_hex());if final_dir.exists(){return load_ready(entry,&final_dir)}let temp=root.join(format!("{}.tmp-{}",generation,std::process::id()));fs::create_dir_all(temp.join("files")).map_err(|e|PayloadError::io("create cache temporary directory",temp.clone(),e))?;fs::copy(archive,temp.join("archive.zip")).map_err(|e|PayloadError::io("copy verified archive",temp.join("archive.zip"),e))?;let (manifest,sources)=archive::extract(entry,archive,&temp.join("files"),progress,cancel)?;fs::write(temp.join("provenance.json"),cache_provenance(entry,&sources)?).map_err(|e|PayloadError::io("write provenance",temp.join("provenance.json"),e))?;match fs::rename(&temp,&final_dir){Ok(())=>load_ready(entry,&final_dir),Err(error) if final_dir.exists()=>{let _=fs::remove_dir_all(&temp);load_ready(entry,&final_dir)},Err(error)=>Err(PayloadError::io("publish cache entry",final_dir,error))}}
fn load_ready(entry:&CatalogEntry,root:&Path)->Result<ReadyGpuPayload,PayloadError>{let bytes=fs::read(root.join("files/payload.json")).map_err(|e|PayloadError::io("read cached payload manifest",root.join("files/payload.json"),e))?;let manifest=PayloadManifest::parse_and_validate(&bytes,entry)?;for file in manifest.files(){let path=root.join("files").join(file.path());let actual=Sha256Digest::hash_reader(File::open(&path).map_err(|e|PayloadError::io("read cached file",path.clone(),e))?)?;if actual!=*file.sha256(){return Err(PayloadError::DigestMismatch{subject:file.path().into(),expected:file.sha256().clone(),actual})}}Ok(ReadyGpuPayload{payload_id:entry.payload_id().into(),generation:entry.archive_sha256().clone(),payload_manifest_sha256:entry.payload_manifest_sha256().clone(),files_directory:root.join("files"),manifest,provenance_path:root.join("provenance.json")})}
